{
  "jsonrpc": "2.0",
  "id": "{{current_req_id}}",
  "method": "tools/call",
  "params": {
    "name": "file_dispute",
    "arguments": {
      "interaction_id": "{{interaction_id}}",
      "reason": "The counterparty reported the outcome as success but the task was not completed as agreed. The deliverable was missing key components specified in the original request.",
      "access_token": "{{access_token}}",
      "evidence": {
        "original_request": "...",
        "actual_delivery": "...",
        "missing_components": ["component_a", "component_b"]
      }
    }
  }
}

{
  "jsonrpc": "2.0",
  "id": "{{current_req_id}}",
  "method": "tools/call",
  "params": {
    "name": "resolve_dispute",
    "arguments": {
      "dispute_id": "{{dispute_id}}",
      "resolution": "upheld",
      "access_token": "{{access_token}}",
      "resolution_note": "Evidence supports the claimant. The counterparty failed to deliver the agreed components."
    }
  }
}

{
  "jsonrpc": "2.0",
  "id": "{{current_req_id}}",
  "method": "tools/call",
  "params": {
    "name": "resolve_dispute",
    "arguments": {
      "dispute_id": "{{dispute_id}}",
      "resolution": "split",
      "access_token": "{{access_token}}",
      "resolution_note": "Partial fault on both sides. Outcome recorded as partial."
    }
  }
}
